419→        let mut ui = NonInteractiveUI::with_ci(OutputMode::Normal, true);
420→        ui.show_workflow_progress(1, 5, Duration::from_secs(1));
421→        // No panic = success. In CI mode this is a no-op.
422→    }
423→}
