/// Convert dialoguer errors to BivvyError, treating EOF as user cancellation.
fn map_dialoguer_err(e: dialoguer::Error) -> BivvyError {
    let io_err: std::io::Error = e.into();
    map_io_err(io_err)
}

/// Convert IO errors to BivvyError, treating EOF as user cancellation.
fn map_io_err(e: std::io::Error) -> BivvyError {
    if e.kind() == std::io::ErrorKind::UnexpectedEof {
        return BivvyError::UserCancelled;
    }
    BivvyError::Io(e)
}

